# B02: the environment running. Kubernetes-style threshold policy on held-out app 8c2b9304,
# day 10, minutes 898-913: 50 server slots, booting countdowns, load against capacity.
# --------------------------------------------------------------------------------------------
class B02_Cluster(Scene):
    BID, DEFAULT = "B02", 13.55

    def construct(self):
        self.begin()
        b = E["burst"]
        m0 = b["minutes"][0]
        steps = list(range(898 - m0, 914 - m0))
        hl = headline("One step is one minute", "One step is", "one minute")
        s, pitch = (0.27, 0.33) if PORTRAIT else (0.5, 0.62)
        slots = VGroup(*[Square(s, stroke_width=3, stroke_color=GREY, fill_color=CREAM, fill_opacity=1)
                         for _ in range(50)]).arrange_in_grid(5, 10, buff=pitch - s)
        legend = VGroup(swatch(TEAL, "serving", "square", 26 if PORTRAIT else 28),
                        swatch(TEAL, "booting", "outline", 26 if PORTRAIT else 28)).arrange(RIGHT, buff=0.22 if PORTRAIT else 0.35)
        bw = 2 * SX if PORTRAIT else 5.6           # bar length for 30,000 requests per minute
        code = (stack("reward = -(cost", "  + late_penalty", "  * late)", size=26, font=MONO, buff=0.05)
                if PORTRAIT else T("reward = -(cost + late_penalty * late)", 30, INK, MONO))
        src = T("src/rl_autoscaler/env.py", 26, SLATE)
        cg = VGroup(src, code).arrange(DOWN, buff=0.1, aligned_edge=LEFT) if not PORTRAIT else code
        clock_proto = T("minute 900", 30 if PORTRAIT else 34, weight="BOLD")

        if PORTRAIT:
            place(clock_proto, left=-SX, top=hl.get_bottom()[1] - 0.22)
            place(slots, left=-SX, top=clock_proto.get_bottom()[1] - 0.14)
            place(legend, left=-SX, top=slots.get_bottom()[1] - 0.14)
            cg = VGroup()   # the reward line is landscape-only; the narration carries it here
            rows_top, rows_left = legend.get_bottom()[1] - 0.2, -SX
        else:
            place(clock_proto, left=-SX, top=hl.get_bottom()[1] - 0.35)
            place(slots, left=-SX, top=clock_proto.get_bottom()[1] - 0.2)
            place(legend, left=-SX, top=slots.get_bottom()[1] - 0.22)
            place(cg, left=-SX, bottom=-SY)
            rows_top, rows_left = slots.get_top()[1], 0.6

        def frame(i):
            run, left = b["running_threshold"][i], b["boot_left_threshold"][i]
            load, capv, late = b["today"][i], b["cap_threshold"][i], b["late_threshold"][i]
            cells = VGroup()
            for j, sq in enumerate(slots):
                c = sq.copy()
                if j < run:
                    c.set_fill(TEAL, 1).set_stroke(TEAL, 3)
                elif j < run + len(left):
                    c.set_stroke(TEAL, 5)
                    c = VGroup(c, T(str(left[j - run] + 1), 26, TEAL, weight="BOLD").scale(0.85).move_to(c))
                cells.add(c)
            clock = place(T(f"minute {m0 + i}", 30 if PORTRAIT else 34, weight="BOLD"), left=clock_proto.get_left()[0],
                          y=clock_proto.get_center()[1])
            rows = VGroup()
            for lab, val, col in (("requests", load, SLATE), ("capacity", capv, TEAL)):
                txt = T(f"{lab}  {k(val)}", 30 if not PORTRAIT else 28)
                bar = VGroup(Rectangle(width=max(min(val, capv if lab == "requests" else val) / 30000 * bw, 0.02),
                                       height=0.26 if PORTRAIT else 0.32, stroke_width=0, fill_color=col, fill_opacity=1))
                if lab == "requests" and load > capv:
                    bar.add(Rectangle(width=(load - capv) / 30000 * bw, height=0.26 if PORTRAIT else 0.32, stroke_width=0,
                                      fill_color=CRIMSON, fill_opacity=1))
                bar.arrange(RIGHT, buff=0)
                rows.add(VGroup(txt, bar).arrange(DOWN, buff=0.1, aligned_edge=LEFT))
            stats = VGroup(T(f"late  {k(late)}", 32 if not PORTRAIT else 30, weight="BOLD"))
            if not PORTRAIT:
                stats.add(T(f"billed  {run + len(left)} servers", 32, weight="BOLD"))
            stats.arrange(DOWN, buff=0.22, aligned_edge=LEFT)
            right = VGroup(rows[0], rows[1], stats)
            if PORTRAIT:
                column(list(right), rows_top, TEXT_FLOOR + 0.1, left=rows_left, min_gap=0.1)
            else:
                column(list(right), rows_top, legend.get_bottom()[1], left=rows_left, min_gap=0.3)
            return VGroup(cells, clock, right)

        cur = frame(steps[0])
        self.P(FadeIn(hl), FadeIn(slots), FadeIn(legend), rt=0.7)
        self.P(FadeIn(cur), rt=0.4)
        tick = (0.80 * self.D - self.el - 0.9) / (len(steps) - 1)
        for i in steps[1:]:
            nxt = frame(i)
            self.remove(cur)
            self.add(nxt)
            cur = nxt
            self.wait(tick)
            self.el += tick
        self.P(FadeIn(cg, shift=UP * 0.1), rt=0.9)
        self.end()


