# B04: minutes from burst start to peak (all training bursts), and one real held-out burst with the
# threshold rule's capacity arriving minutes late.
# --------------------------------------------------------------------------------------------
def burst_chart(box, xlabel=None):
    b = E["burst"]
    ms = b["minutes"]
    ax = axes(box, [(0, "0"), (15000, "15k"), (30000, "30k")] if PORTRAIT else
              [(0, "0"), (10000, "10k"), (20000, "20k"), (30000, "30k")],
              [(900, "900"), (905, "905"), (910, "910"), (915, "915")] if not PORTRAIT else
              [(900, "900"), (910, "910")], xlabel)
    today = box.line(ms, b["today"], SLATE, 7)
    cap_t = box.line(ms, b["cap_threshold"], CRIMSON, 6, step=True)
    wait_t = VGroup(*[box.column(m + 0.5, c, l, 0.7, CRIMSON, 0.35)
                      for m, l, c in zip(ms, b["today"], b["cap_threshold"]) if l > c])
    yest = DashedVMobject(box.line(ms, b["yesterday"], GREY, 5), num_dashes=70)
    cap_y = box.line(ms, b["cap_yesterday"], TEAL_LINE, 7, step=True)
    wait_y = VGroup(*[box.column(m + 0.5, c, l, 0.7, CRIMSON, 0.35)
                      for m, l, c in zip(ms, b["today"], b["cap_yesterday"]) if l > c])
    if PORTRAIT:   # tinted columns over the navy line mix to an ink-like purple that GATE T reads as text
        wait_t.set_z_index(-1)
        wait_y.set_z_index(-1)
    return ax, today, cap_t, wait_t, yest, cap_y, wait_y


