# B07: next week. The observation from env.py _obs() (25 numbers) feeds a PPO policy; the bar.
# --------------------------------------------------------------------------------------------
class B07_NextWeek(Scene):
    BID, DEFAULT = "B07", 7.96

    def construct(self):
        self.begin()
        R = E["results"]
        hl = headline("Next week: train a PPO agent", "Next week:", "train PPO")
        cell = 0.14 if PORTRAIT else 0.3
        groups = [(10, SLATE, ("last 10 min",)), (10, GREY, ("yesterday, next 10",) if not PORTRAIT else ("yesterday",)),
                  (5, TEAL, ("servers, queue, time",) if not PORTRAIT else ("servers,", "queue, time"))]
        strip = VGroup()
        for n, col, lab in groups:
            g = VGroup(*[Square(cell, stroke_width=2, stroke_color=CREAM, fill_color=col, fill_opacity=1)
                         for _ in range(n)]).arrange(RIGHT, buff=0.03)
            t = stack(*lab, size=26, buff=0.04)
            strip.add(VGroup(g, t).arrange(RIGHT if PORTRAIT else DOWN, buff=0.15,
                                           aligned_edge=LEFT if not PORTRAIT else ORIGIN))
        strip.arrange(DOWN if PORTRAIT else RIGHT, buff=0.18 if PORTRAIT else 0.4, aligned_edge=LEFT if PORTRAIT else UP)
        title = T("what the agent sees: 25 numbers", 28, SLATE)
        ppo = Group(Group(T("PPO", 44, weight="BOLD"), logo("colab", 0.4)).arrange(RIGHT, buff=0.2),
                    T("Stable-Baselines3", 28)).arrange(DOWN, buff=0.1)
        frame = SurroundingRectangle(ppo, buff=0.2, stroke_color=INK, stroke_width=4, corner_radius=0.15)
        pg = Group(frame, ppo)
        act = stack("add or remove", "up to 5 servers", size=30, buff=0.05)
        bar = stack("The bar: late under 1.17%", f"at {k(R['yesterday'][0])} server-minutes a day", size=30,
                    weight="BOLD", buff=0.08) if not PORTRAIT else \
            stack("The bar:", "under 1.17% late", f"at {k(R['yesterday'][0])}", "server-min a day",
                  size=26, weight="BOLD", buff=0.04)
        bg = VGroup(SurroundingRectangle(bar, buff=0.2, stroke_color=TEAL, stroke_width=6, corner_radius=0.12), bar)
        if PORTRAIT:
            column([strip, pg, bg], hl.get_bottom()[1] - 0.25, TEXT_FLOOR, left=-SX, min_gap=0.3)
            a1 = Arrow(strip.get_bottom(), pg.get_top(), buff=0.05, stroke_color=INK, stroke_width=4,
                       tip_length=0.14).set_x(pg.get_center()[0])
            a2, act, title = VGroup(), VGroup(), VGroup()
        else:
            column([title, strip], hl.get_bottom()[1] - 0.35, 0.6, left=-SX, min_gap=0.2)
            place(pg, left=-SX + 0.4, top=strip.get_bottom()[1] - 0.75)
            place(act, left=pg.get_right()[0] + 1.3, y=pg.get_center()[1])
            place(bg, right=SX, bottom=-SY + 0.6)
            a1 = Arrow([pg.get_center()[0], strip.get_bottom()[1], 0], pg.get_top(), buff=0.1, stroke_color=INK,
                       stroke_width=4, tip_length=0.18)
            a2 = Arrow(pg.get_right(), act.get_left(), buff=0.12, stroke_color=INK, stroke_width=4, tip_length=0.18)
        self.P(FadeIn(hl), FadeIn(title), LaggedStart(*[FadeIn(g) for g in strip], lag_ratio=0.3), rt=1.2)
        self.at(0.30)
        self.P(GrowArrow(a1), FadeIn(pg), rt=0.8)
        self.P(*([GrowArrow(a2), FadeIn(act)] if not PORTRAIT else [Wait()]), rt=0.6)
        self.at(0.58)
        self.P(Create(bg[0]), FadeIn(bar), rt=0.8)
        self.end()


# --------------------------------------------------------------------------------------------
# B10: title restate. The full HAI mark, the title with a terracotta period, the handle, the repo.
# --------------------------------------------------------------------------------------------
class B10_Outro(Scene):
    def construct(self):
        self.camera.background_color = CREAM
        D = beat_seconds("B10", 4.5)
        mark = hai_mark(1.1 if PORTRAIT else 1.5)
        lines = (("Why Autoscalers", "Need Yesterday's", "Traffic.") if PORTRAIT else
                 ("Why Autoscalers Need", "Yesterday's Traffic."))
        title = VGroup(*[T(s, 52 if PORTRAIT else 80, INK, SERIF, t2c={".": TERRA}) for s in lines]).arrange(DOWN, buff=0.05)
        title.scale_to_fit_width(min(title.width, 2 * SX - 0.1))   # the longest portrait line must fit 9:16
        handle = T("@HumanitariansAI", 28 if PORTRAIT else 36, weight="BOLD")
        repo = (stack("github.com/", "lakshdhamija/", "rl-autoscaler", size=26, color=SLATE, buff=0.05, aligned=ORIGIN)
                if PORTRAIT else T("github.com/lakshdhamija/rl-autoscaler", 28, SLATE))
        g = VGroup(mark, title, handle, repo).arrange(DOWN, buff=0.28 if PORTRAIT else 0.45).move_to(ORIGIN)
        if PORTRAIT:
            place(g, top=SY - 0.2)
        rule = Line(LEFT, RIGHT, stroke_color=GOLD, stroke_width=8).set_width(min(title.width, 2 * SX))
        rule.move_to([0, (title.get_bottom()[1] + handle.get_top()[1]) / 2, 0])
        self.play(FadeIn(mark, shift=UP * 0.1), FadeIn(title), run_time=0.6)
        self.play(Create(rule), FadeIn(handle), FadeIn(repo), run_time=0.4)
        self.wait(max(D - 1.0, 0.1))
